import type { ReactNode } from 'react'
import Image from 'next/image'
import { PlayCircle } from 'lucide-react'

import { HoverButton } from '@/components/library/primitives/HoverButton'
import { cn } from '@/lib/utils'

export type BannerEditorialProps = {
  eyebrow?: string
  title: ReactNode
  description?: string
  images: readonly { src: string; alt: string }[]
  primaryAction?: { label: string; href: string }
  secondaryAction?: { label: string; href: string; icon?: ReactNode }
  mediaVariant?: 'device' | 'stack' | 'poster'
  tone?: 'light' | 'dark' | 'warm'
  className?: string
}

const tones = {
  light: 'bg-white text-slate-950',
  dark: 'bg-black text-white',
  warm: 'bg-[#f2eee7] text-slate-950',
}

export function BannerEditorial({
  eyebrow,
  title,
  description,
  images,
  primaryAction,
  secondaryAction,
  mediaVariant = 'device',
  tone = 'light',
  className,
}: BannerEditorialProps) {
  const firstImage = images[0]
  const secondImage = images[1]

  return (
    <section
      className={cn('relative overflow-hidden', tones[tone], className)}
      aria-labelledby="banner-editorial-title"
    >
      <div className="container grid min-h-[720px] items-center gap-12 py-20 lg:grid-cols-[1.05fr_.95fr] lg:py-28">
        <div className="relative z-10 max-w-3xl">
          {eyebrow ? (
            <p className="mb-6 text-xs font-bold uppercase tracking-[0.24em] text-primary">
              {eyebrow}
            </p>
          ) : null}
          <h1
            id="banner-editorial-title"
            className="text-5xl font-black uppercase leading-[0.95] tracking-[-0.04em] sm:text-6xl lg:text-8xl"
          >
            {title}
          </h1>
          {description ? (
            <p
              className={cn(
                'mt-8 max-w-xl text-base leading-8',
                tone === 'dark' ? 'text-white/65' : 'text-slate-600',
              )}
            >
              {description}
            </p>
          ) : null}

          {primaryAction || secondaryAction ? (
            <div className="mt-9 flex flex-wrap gap-3">
              {primaryAction ? (
                <HoverButton
                  href={primaryAction.href}
                  effect="expand-icon"
                  size="lg"
                  className="rounded-none px-7"
                >
                  {primaryAction.label}
                </HoverButton>
              ) : null}
              {secondaryAction ? (
                <HoverButton
                  href={secondaryAction.href}
                  effect="lift"
                  variant="outline"
                  size="lg"
                  icon={secondaryAction.icon ?? <PlayCircle className="h-4 w-4" aria-hidden />}
                  iconPosition="left"
                  className={cn(
                    'rounded-none px-7',
                    tone === 'dark' &&
                      'border-white/30 bg-transparent text-white hover:bg-white/10',
                  )}
                >
                  {secondaryAction.label}
                </HoverButton>
              ) : null}
            </div>
          ) : null}
        </div>

        <div className="relative mx-auto h-[560px] w-full max-w-lg">
          {firstImage ? (
            <figure
              className={cn(
                'absolute overflow-hidden bg-muted shadow-2xl',
                mediaVariant === 'device' &&
                  'inset-y-0 right-6 w-[68%] rounded-[3rem] border-[10px] border-slate-900',
                mediaVariant === 'stack' &&
                  'left-0 top-10 h-[78%] w-[72%] rotate-[-5deg] rounded-3xl',
                mediaVariant === 'poster' && 'inset-0 rounded-none',
              )}
            >
              <Image
                src={firstImage.src}
                alt={firstImage.alt}
                fill
                priority
                className="object-cover"
                sizes="(min-width: 1024px) 40vw, 85vw"
              />
            </figure>
          ) : null}

          {secondImage ? (
            <figure
              className={cn(
                'absolute overflow-hidden bg-muted shadow-2xl',
                mediaVariant === 'device' &&
                  'bottom-6 right-0 h-[58%] w-[58%] rounded-3xl border-8 border-background',
                mediaVariant === 'stack' &&
                  'bottom-4 right-0 h-[68%] w-[68%] rotate-6 rounded-3xl border-8 border-background',
                mediaVariant === 'poster' &&
                  'bottom-8 right-[-8%] h-[42%] w-[62%] border-8 border-background',
              )}
            >
              <Image
                src={secondImage.src}
                alt={secondImage.alt}
                fill
                className="object-cover"
                sizes="(min-width: 1024px) 28vw, 60vw"
              />
            </figure>
          ) : null}
        </div>
      </div>
    </section>
  )
}

import type { ButtonHTMLAttributes, ReactNode } from 'react'
import Link from 'next/link'
import { ArrowRight } from 'lucide-react'

import { Button, type ButtonProps } from '@/components/ui/button'
import { cn } from '@/lib/utils'

export type HoverButtonEffect = 'lift' | 'shine' | 'slide' | 'glow' | 'underline' | 'expand-icon'

export interface HoverButtonProps extends Omit<
  ButtonHTMLAttributes<HTMLButtonElement>,
  'children'
> {
  children: ReactNode
  href?: string
  effect?: HoverButtonEffect
  variant?: ButtonProps['variant']
  size?: ButtonProps['size']
  icon?: ReactNode
  iconPosition?: 'left' | 'right'
}

const effectClasses: Record<HoverButtonEffect, string> = {
  lift: 'transition-all duration-300 hover:-translate-y-1 hover:shadow-lg active:translate-y-0',
  shine:
    'relative overflow-hidden before:absolute before:inset-y-0 before:-left-1/2 before:w-1/3 before:-skew-x-12 before:bg-white/30 before:blur-sm before:transition-all before:duration-500 hover:before:left-[120%]',
  slide:
    'relative overflow-hidden border-primary bg-transparent text-primary before:absolute before:inset-0 before:-translate-x-full before:bg-primary before:transition-transform before:duration-300 hover:text-primary-foreground hover:before:translate-x-0',
  glow: 'transition-all duration-300 hover:shadow-[0_0_28px_hsl(var(--primary)/0.45)]',
  underline:
    'relative rounded-none bg-transparent text-foreground after:absolute after:bottom-1 after:left-1/2 after:h-0.5 after:w-0 after:bg-primary after:transition-all after:duration-300 hover:bg-transparent hover:after:left-0 hover:after:w-full',
  'expand-icon': 'group transition-all duration-300 hover:pr-6',
}

export function HoverButton({
  children,
  href,
  effect = 'lift',
  variant = 'default',
  size = 'default',
  icon,
  iconPosition = 'right',
  className,
  type = 'button',
  ...props
}: HoverButtonProps) {
  const trailingIcon =
    effect === 'expand-icon' && !icon ? <ArrowRight className="h-4 w-4" aria-hidden /> : icon

  const content = (
    <>
      {iconPosition === 'left' ? trailingIcon : null}
      <span className="relative z-10">{children}</span>
      {iconPosition === 'right' ? trailingIcon : null}
    </>
  )

  const classes = cn(
    'gap-2',
    effectClasses[effect],
    effect === 'expand-icon' &&
      '[&_svg]:transition-transform [&_svg]:duration-300 hover:[&_svg]:translate-x-1',
    className,
  )

  if (href) {
    return (
      <Button asChild variant={variant} size={size} className={classes}>
        <Link href={href}>{content}</Link>
      </Button>
    )
  }

  return (
    <Button type={type} variant={variant} size={size} className={classes} {...props}>
      {content}
    </Button>
  )
}

import * as React from 'react'
import { Slot } from '@radix-ui/react-slot'
import { cva, type VariantProps } from 'class-variance-authority'

import { cn } from '@/lib/utils'

const buttonVariants = cva(
  'inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-md text-sm font-medium transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0',
  {
    variants: {
      variant: {
        default: 'bg-primary text-primary-foreground shadow hover:bg-primary/90',
        destructive: 'bg-destructive text-destructive-foreground shadow-sm hover:bg-destructive/90',
        outline:
          'border border-input bg-background shadow-sm hover:bg-accent hover:text-accent-foreground',
        secondary: 'bg-secondary text-secondary-foreground shadow-sm hover:bg-secondary/80',
        ghost: 'hover:bg-accent hover:text-accent-foreground',
        link: 'text-primary underline-offset-4 hover:underline',
      },
      size: {
        default: 'h-9 px-4 py-2',
        sm: 'h-8 rounded-md px-3 text-xs',
        lg: 'h-10 rounded-md px-8',
        icon: 'h-9 w-9',
      },
    },
    defaultVariants: {
      variant: 'default',
      size: 'default',
    },
  },
)

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>, VariantProps<typeof buttonVariants> {
  asChild?: boolean
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, asChild = false, ...props }, ref) => {
    const Comp = asChild ? Slot : 'button'
    return (
      <Comp className={cn(buttonVariants({ variant, size, className }))} ref={ref} {...props} />
    )
  },
)
Button.displayName = 'Button'

export { Button, buttonVariants }

import { type ClassValue, clsx } from 'clsx'
import { twMerge } from 'tailwind-merge'

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}
